$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$route = Decode ""

$financePath = Join-Path $root "app\api\provider\finance\route.ts"
$auditPath = Join-Path $root "app\api\provider\finance-audit\route.ts"

foreach ($path in @($financePath, $auditPath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "13.05c : fichier requis introuvable : $path"
    }
}

$finance = [System.IO.File]::ReadAllText($financePath)
$audit = [System.IO.File]::ReadAllText($auditPath)

if (-not $finance.Contains("KLYX_GROUP_AWARE_FINANCE_COUNTS_13_04")) {
    throw "13.05c : KLYX 13.04 introuvable."
}

if (-not $audit.Contains("KLYX_GROUP_FINANCE_AUDIT_API_13_03")) {
    throw "13.05c : KLYX 13.03 introuvable."
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

Copy-Item -LiteralPath $financePath -Destination ($financePath + ".bak-13-05c-" + $timestamp) -Force

[System.IO.File]::WriteAllText($financePath, $route, $utf8)

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.05c APPLIQUE"
Write-Host "======================================"
Write-Host "total_amount_cents obligatoire : NON"
Write-Host "Schema booking_groups : DETECTE RUNTIME"
Write-Host "Booking simple : LEDGER"
Write-Host "Booking groupe : TOTAL CANONIQUE SI PRESENT"
Write-Host "Fallback ancien groupe : LEDGER"
Write-Host "Stripe modifie : NON"
Write-Host "Migration : AUCUNE"
Write-Host "======================================"
